import sympy

def is_prime(n):
    return sympy.isprime(n)

def check_good(x, y, z):
    try:
        # Calculate y^x * z^y * x^z
        # Use pow(base, exp) but need to be careful with negative bases and fractional results
        # y^x * z^y * x^z = p

        # We only care if it's a positive prime, so the result must be an integer
        # Use fractions to handle negative exponents
        from fractions import Fraction

        val = Fraction(1)

        # y^x
        val *= Fraction(y)**x
        # z^y
        val *= Fraction(z)**y
        # x^z
        val *= Fraction(x)**z

        if val.denominator == 1:
            return is_prime(val.numerator)
    except (ZeroDivisionError, OverflowError, ValueError):
        pass
    return False

good_triples = []
limit = 10
for x in range(-limit, limit + 1):
    if x == 0: continue
    for y in range(-limit, limit + 1):
        if y == 0: continue
        for z in range(-limit, limit + 1):
            if z == 0: continue
            if check_good(x, y, z):
                good_triples.append((x, y, z))

# Sort by x^2 + y^2 + z^2
good_triples.sort(key=lambda t: t[0]**2 + t[1]**2 + t[2]**2)

for t in good_triples[:20]:
    print(f"Triple: {t}, x^2+y^2+z^2: {t[0]**2 + t[1]**2 + t[2]**2}")

